namespace MmaManager.Core.Sim.Generation.Origins;

public static partial class OriginsChapters
{
    // ===================== ERA 5: THE BOOM (2004-2013) =====================
    private static OriginsChapter[] Era5() => new[]
    {
        C("breakout-tv-moment", 5, "The Night Everyone Watched", 132, 190, A("cable-sports-channel", "unified-rules", "weight-ladder-middle"),
            "A televised title fight between two fighters who are each already famous is seen by far more people than any sport on the same night.",
            World("BothFightersFameAtLeast", 50),
            A(),
            A("Mainstream attention: public interest rises sharply for about three years; every media deal pays more; the sport's pull on casual fans doubles."),
            N("{Org}'s {Fighter} takes the whole country's Saturday",
              "A rain-soaked weekend, two cancelled games and a channel with a hole in its schedule: {Partner} puts {Org}'s title fight on live, and {Fighter} does the rest. By the third round the switchboard at the network is jammed, by the fifth the national papers have sent photographers and by the end the studio is shaking. {Founder} watches from the corner with the cold calm of a man who has waited ten years for this. Monday morning, everyone at every office has an opinion."),
            N("{Org} and {Fighter} are the night's talk of the nation",
              "On a quiet Saturday, {Partner} has broadcast {Org}'s title fight to the largest audience the sport has ever had. {Fighter} did not disappoint, and neither did his opponent. By Monday the ratings were the story. Every promotion in the world is calling its agents, and every network in the world is calling its lawyers. Competing networks have asked the same question all week: where was this when we needed a Saturday?"),
            N("Everybody tunes in",
              "{Year}. It begins as an afterthought: a title fight between two fighters who dislike each other, on a night when the network has no better ideas. Within a round the audience has doubled; by the finish it has tripled. The sport that began in a garage and survived a decade of editorials is suddenly the thing everyone saw. Newspapers that wrote the editorials now write the profiles. The following Monday, every network that ignored the sport asks the same question: how soon can we have it?"),
            "The breakout: a televised title fight becomes the night everyone watched."),

        C("prime-time-network-deal", 5, "A National Network Picks It Up", 144, 204, A("breakout-tv-moment"),
            "The first promotion to sign a national over-the-air prime-time deal.",
            First("SignMedia:PrimeBroadcast"),
            A("Media:PrimeBroadcast"),
            A("The big stage and the strictest partner: prime-time slots, large fees and tough standards of conduct."),
            N("{Org} walks onto prime time with {Partner}",
              "{Partner}, one of the country's big three broadcasters, has given {Org} a Saturday night slot and a multi-year contract. {Founder} signs on a stage with a banner behind him and shakes hands with a man who used to deny the sport existed. The money is the largest in the sport's history. The conditions are almost as large: standards of conduct, family-hour language and a clean image. The audience, at last, is the whole country."),
            N("{Partner} puts {Org} on the biggest stage",
              "{Org} has signed a prime-time deal with {Partner}, a national broadcaster, the first time the sport has been on over-the-air television at an hour when everyone is at home. The fee is huge and the standards are strict. Rival promoters are already in talks with the other networks. Its standards department has already sent over a two-page memo about language, entrances and the use of the word 'cage'."),
            N("The big three open the door",
              "{Year}. After the night everyone watched, the national networks, which kept the sport at arm's length for a decade, change their minds in a week. {Partner} is the first to sign, and the contract it offers is both a prize and a leash: a prime-time slot, large fees and rules about language, conduct and what may be shown. The sport that once could not buy a pay-per-view slot now has a seat at the table with every other major sport."),
            "Prime time: {Partner} signs the first national network deal."),

        C("boom-new-promotions", 5, "Everyone Wants a Promotion", 144, 210, A("breakout-tv-moment"),
            "Follows the breakout: new promotions are founded at a much higher rate for several years.",
            World("PromotionsAtLeast", 14),
            A(),
            A("New promotions are founded at a higher rate for several years; a wave of founders, many with money and few with plans."),
            null, null,
            N("A promotion on every corner",
              "{Year}. When television discovers a sport, so does every investor. In a few seasons, dozens of new promotions appear: a former footballer, a casino owner, a nightclub chain, a retired champion with a gym and a plan. Some are serious and well-funded. Many are neither. A few will become household names; most will not survive their second year. For fighters it is a golden age of choice. For veteran promoters it is a sudden, expensive, noisy competition."),
            "The boom: new promotions open on every corner.",
            "A world wave; no player variant (the player may found one at any time)."),

        C("first-acquisition", 5, "The First Takeover", 150, 220, A("breakout-tv-moment"),
            "The first promotion to buy another.",
            First("AcquireRival"),
            A("Acquisitions"),
            A("Promotions can buy one another; rosters, contracts and belts move with the sale."),
            N("{Org} buys a rival",
              "The announcement is two paragraphs long and shakes the sport: {Org} has bought a rival outright, brand, roster and contracts, and will fold it into its own. {Founder} calls it consolidation. Rivals call it something else. The fighters, who have been told they are now employees of a larger company, call their agents. The first takeover will not be the last, and everyone in the business knows it."),
            N("{Org} swallows a competitor",
              "{Org} has acquired a rival promotion, the first takeover the sport has seen. The price was not disclosed. The roster, the belts and the contracts all move to {Org}. The smaller promotions are asking themselves the one question that matters: who will be next? Analysts expect more such deals this year, and several smaller promoters have already hired lawyers to read their own contracts."),
            N("A promotion changes hands",
              "{Year}. Mergers are what happen to businesses that grow too quickly: the first one in the sport arrives as a press release. A larger promotion buys a smaller one, takes over its contracts and its belts, and sets about the business of absorbing its fans. The announcement sets off a scramble across the industry. Small promotions suddenly wonder what they are worth; large ones wonder whom they could afford."),
            "The first takeover: one promotion buys another."),

        C("weight-ladder-bantam", 5, "The Bantamweights Arrive", 132, 200, A("weight-ladder-lower"),
            "The first promotion to crown a champion in the bantamweight class.",
            First("CrownChampionInClass:Bantamweight"),
            A("WeightClass:Bantamweight"),
            A("The bantamweight class opens."),
            N("{Org} opens the bantamweight division",
              "Under one hundred and forty pounds the sport finds its quickest fighters, and {Org} gives them a division of their own. {Fighter} wins the first title in {City}, and the crowd, expecting something small, gets something blindingly fast. {Founder} has already booked the next three cards. The ladder of divisions is nearly full, and the men at the bottom of it have made themselves impossible to ignore."),
            N("{Org} crowns {Fighter} at bantamweight",
              "{Fighter} is the first bantamweight champion, crowned by {Org} in {City}. The division is lighter than anything the sport has tried and faster than anything it has seen. Rival promotions had called it a sideshow; they are now ringing round for bantamweights. The new division will have eight ranked contenders by the end of the season, and a waiting list of promoters."),
            N("The smaller men get a champion",
              "{Year}. Below featherweight the sport has been missing a class of its own, and as the pool of fighters grows, someone finally opens it. Bantamweights fight at a pace that surprises the audience: quicker hands, quicker feet, more scrambling. Within a year the division has more depth than the middle of the ladder. Promoters are discovering that crowds love fast men, and that fast men are cheap."),
            "Bantamweight opens: the smaller men get a champion."),

        C("womens-first-division", 5, "A Division of Their Own", 156, 216, A("womens-resistance", "unified-rules"),
            "The first promotion to open a women's division with a belt.",
            First("CrownChampionInClass:Strawweight"),
            A("WomensDivisions", "WeightClass:Strawweight"),
            A("Women enter the talent intake in numbers; promotions can open women's divisions; the lightest class (115 lb) opens with them."),
            N("{Org} opens the first women's division",
              "{Org} has done what no one else would: a division for women, a belt and a schedule. {Fighter} wins the first title in {City}, and the crowd, which came for a curiosity, stays for the contest. {Founder} has been criticised by two commissions and congratulated by a third. Women across the world who trained in the shadows start to wonder whether they might be paid to do it."),
            N("{Org} crowns the first women's champion",
              "{Fighter} is the first champion of a women's division, crowned by {Org} in {City}. The belt is real, the purses are modest, the fights are good. Several promoters say they will wait and see. The fighters, for the first time, will not have to. Within a week, two commissions have asked for the rule book and one has asked for a tape."),
            N("The first women's belt",
              "{Year}. After a decade of one-off bouts and closed doors, a single promotion decides that women's fights can sustain a division. The first belt is contested in the lightest class, at one hundred and fifteen pounds. The purses are small and the card is long. The reviews are better than anyone expected. Within a year, women's divisions appear in other promotions' plans, and gyms that never taught a woman are rapidly rearranging their timetables."),
            "The first women's division: a belt of their own."),

        C("scene-gulf-cape-andes", 5, "Money and Mountains: the Gulf, Turkey, the Cape and Colombia", 150, 220, A("scene-newzealand-china-philippines-singapore"),
            "The first promotion to hold a card in one of these countries.",
            First("HoldEventInNewCountry"),
            A("CountryScene:UAE", "CountryScene:TUR", "CountryScene:RSA", "CountryScene:COL"),
            A("Scenes in the Emirates, Turkey, South Africa and Colombia wake; Gulf arenas pay large fees to visiting promotions."),
            N("{Org} arrives in {City}",
              "{Org} has taken a card to {City}, {Country}, and the welcome includes a government minister, a marching band and a very large cheque. Local gyms had been waiting for years. {Founder} says it is a milestone and then makes an appointment to see the venue's owner about the next one. A new scene has a mainstream footing from its first night."),
            N("{Org} opens in {City}",
              "{City}, {Country}, has its first major card, and {Org} is the host. The reception was extravagant and the cheques were larger. Every other promotion is now asking the same question: how soon can we go there? Every seat was taken, the carnival atmosphere lasted past midnight and the local fighters, to a man, asked for contracts. The home promotions have a new rival and a new talent pool to think about."),
            N("New money and new mountains",
              "{Year}. The sport reaches four new places in the same few years. In the Emirates, a ruling family builds an arena and invites promoters to fill it at a price that would have built three halls elsewhere. In Turkey, wrestling clubs five hundred years old produce challengers. In South Africa, a rugby nation takes to the cage. In Colombia, boxers and jiu-jitsu students pack the first hall in Bogota."),
            "Scenes wake in the Emirates, Turkey, South Africa and Colombia."),

        C("global-brands-arrive", 5, "The World's Brands Take a Seat", 168, 230, A("national-brands-sign-on", "prime-time-network-deal"),
            "The first promotion to sign a global brand: an airline, a sportswear maker or a drinks company with customers on every continent.",
            First("SignSponsor:Global"),
            A("Sponsor:Global"),
            A("Global brands sponsor title fights of continental and international promotions that have a famous star."),
            N("{Partner} signs {Org} to a world deal",
              "The signature on the page belongs to a company with customers in a hundred countries. {Partner} has made {Org} its first partner in combat sport, with a deal that covers every title fight in every venue on the schedule. {Founder} describes it as a handshake across the world. {Fighter}, whose face is already on the first campaign poster, describes it as a very long advert and a very large cheque."),
            N("{Partner} chooses {Org}",
              "A truly global company, {Partner}, has signed {Org}, with a deal that makes headlines on three continents. The terms are strict: title fights, stars and a clean record. The sport has been admitted to the company of the Olympics and the football leagues, at least in the minds of the advertisers. Its chief executive, announcing the deal, said only that the company goes where the crowds go."),
            N("The world's brands",
              "{Year}. A company that sells watches in every capital, a sportswear maker, an airline: the biggest brands in the world have until now never put their names next to a fight. Now they do. The contracts are enormous and the conditions are tight: stars, title fights, no scandals. The sport gets money, polish and a new kind of respect. In return it gets a new kind of pressure."),
            "Global brands arrive: a company with customers in a hundred countries signs on."),

        C("womens-first-star", 5, "The First Woman Everybody Knows", 180, 240, A("womens-first-division"),
            "A woman fighter's fame passes the threshold that made the first men stars.",
            World("WomensStarFameAtLeast", 55),
            A(),
            A("Women's fame builds the same way men's does; a women's star can carry a card and a sponsor."),
            N("{Fighter} is the name on the poster",
              "She has won every fight since the division began. She has given a thousand interviews and refused to be anyone's curiosity. {Fighter} of {Org} has become the first woman in the sport to be a household name, and the posters for her next fight carry only her face. {Founder} has stopped saying the division is an experiment. {Fighter} has been calling it a sport for years."),
            N("{Fighter} of {Org} becomes the first women's star",
              "{Fighter} is the first woman the sport has produced whom strangers recognise, and {Org} is making the most of it. The posters, the interviews and the sponsors have all arrived. Rival promoters who dismissed the division are asking for her number. Her next fight is already on pay-per-view, and the arena in {City} has sold out its first three rows to sponsors."),
            N("A woman on every wall",
              "{Year}. Every sport has its first star. The sport's first woman to reach that level, {Fighter}, did it with a long streak of finishes, a calm manner and a refusal to be described as anything but a fighter. Magazines that have never covered the sport put her on their covers. Parents who had never allowed a daughter near a gym telephone one. Within a year her name is the first one most people give when asked to name a fighter."),
            "The first women's star: {Fighter} becomes a name on every wall."),

        C("consolidation-wave", 5, "The Big Ones Buy the Middle", 192, 260, A("first-acquisition", "boom-new-promotions"),
            "Acquisitions pass a threshold and the middle of the pyramid begins to thin.",
            World("AcquisitionsAtLeast", 4),
            A(),
            A("AI acquisitions become common; the number of mid-sized promotions falls; the big few grow."),
            null, null,
            N("The middle thins out",
              "{Year}. The boom brought hundreds of promotions; the money brought the buyers. In a few years the middle of the sport is consolidated: three or four giants own what used to be twenty independent promotions, and the regional shows that remain are either feeders or boutiques. Fighters who were employed by a dozen small names are now contracted to one company. It is more efficient and less romantic, and the founders who sold are either delighted or deeply regretful."),
            "The consolidation wave: a few giants buy the middle of the sport.",
            "A world wave; the player may buy or be bought through ordinary acquisition play."),

        C("womens-headline-card", 5, "A Women's Fight Headlines", 204, 260, A("womens-first-star"),
            "A women's fight is the main event of a card on a national platform.",
            World("WomensDivisionBoutsAtLeast", 12),
            A(),
            A("Women's bouts can headline; women's title fights draw as men's do at the same level."),
            N("{Org} puts a woman in the main event",
              "For the first time the main event on a major card is a women's title fight, and {Org} has chosen {Fighter} as its headliner. The arena in {City} is full by the first prelim. {Founder} walks to the commentary desk before the last fight and is asked whether this is a historic night. 'It is a good fight,' says {Founder}. 'The history is for later.'"),
            N("{Org} headlines with a women's title fight",
              "{Org} has put a women's title fight at the top of its card in {City}, and {Fighter} is the face. The tickets are gone. The broadcast is live. The sport has reached the point where nobody asks why. The commentators are careful not to call it historic until the final bell, and then they do. The other three fights on the card are all, for once, being talked about as the undercard."),
            N("The main event",
              "{Year}. It was a question that no one used to ask because the answer was obvious: could a women's fight headline a card? The answer, on a Saturday night in a full arena, is yes. The two fighters, both champions of their classes, put on a better fight than anything else on the schedule. The broadcast is among the most-watched of the year. Nobody afterwards mentions that this was ever in doubt."),
            "A women's fight headlines a major card."),

        C("weight-ladder-flyweight", 5, "The Flyweights Come Last", 180, 252, A("weight-ladder-bantam"),
            "The first promotion to crown a flyweight champion.",
            First("CrownChampionInClass:Flyweight"),
            A("WeightClass:Flyweight"),
            A("The flyweight class opens; the sport's men's ladder is complete."),
            N("{Org} crowns the smallest champion",
              "{Fighter} is the first man to hold a flyweight title, crowned in {City} by {Org}. He is the lightest champion the sport has had, and he is the fastest. The crowd watches him with the stunned look of people who have seen a magician. {Founder} has been waiting for this class for years and says it was always going to be the last piece."),
            N("{Org} opens the flyweight class",
              "{Org} has launched a flyweight division and crowned {Fighter} in {City}. The men in this class are smaller than anyone has fought at, and they fight at a pace that startles even regular viewers. The men's ladder now runs from heavy to fly. Scouts say the best fighters in the class have been in the gyms for years, waiting for a belt."),
            N("The ladder is complete",
              "{Year}. The sport began with one weight and no divisions at all. Now the last men's class opens: flyweight, under one hundred and twenty-five pounds, a division of the fastest athletes in the sport. The ladder runs from the biggest heavyweights down to the smallest men who can be matched fairly. Promoters who dismissed it as a gimmick now find that the flyweights provide more finishes per card than any other division."),
            "The last men's class: flyweight completes the ladder."),
    };
}
